def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.28))

    pressure = max(prev_bids) if prev_bids else DAILY_SALARY * 0.75
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else DAILY_SALARY * 0.7

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 0.75
    elif hp <= 4:
        danger += 0.45
    elif hp <= 6:
        danger += 0.2

    if no_water_days >= 2:
        danger += 0.8
    elif no_water_days == 1:
        danger += 0.35

    if day >= 8:
        danger += 0.15

    base = DAILY_SALARY * (0.34 + 0.22 * scarcity + 0.28 * danger)

    if supply >= 22 and hp >= 7 and no_water_days == 0:
        bid = min(base, DAILY_SALARY * 0.38)
    elif pressure < DAILY_SALARY * 0.9:
        bid = max(base, pressure + 1.2)
    elif pressure < DAILY_SALARY * 1.3:
        if danger >= 0.6:
            bid = max(base, pressure + 2.0)
        else:
            bid = max(base, avg_prev * 0.82)
    else:
        if danger >= 0.85:
            bid = max(base, min(pressure * 0.92, DAILY_SALARY * 1.45))
        else:
            bid = max(base, DAILY_SALARY * 0.42)

    if urgent_opp >= 2:
        bid += 4.0
    elif urgent_opp == 0 and supply >= 20:
        bid -= 3.0

    if rich_opp >= 3 and danger >= 0.5:
        bid += 3.5

    if budget < DAILY_SALARY * 2:
        bid = min(bid, budget * 0.58)
    elif budget < DAILY_SALARY * 4:
        bid = min(bid, budget * 0.42)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, DAILY_SALARY * 0.95)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if day_context['supply'] < 18:
        return min(my_status['budget'], avg_prev * 1.1)

    return min(my_status['budget'], max(30.0, avg_prev * 0.95))
